-- Synthetic lineage and trusted administrator/editor for transaction-local checks.
CREATE FUNCTION pg_temp.body(payload jsonb) RETURNS jsonb LANGUAGE sql AS $$ SELECT payload||'{"evidence":{"record":[{"assertion_id":"57000000-0000-0000-0000-000000000001","role":"supporting"}]}}'::jsonb $$;
CREATE FUNCTION pg_temp.save(kind text,payload jsonb,entity uuid DEFAULT NULL,working uuid DEFAULT NULL,published uuid DEFAULT NULL) RETURNS uuid LANGUAGE sql AS $$ SELECT governance.save_revision(kind,entity,working,published,pg_temp.body(payload),'Synthetic source-backed choice') $$;
CREATE FUNCTION pg_temp.publish(rev uuid,previous uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql AS $$ DECLARE d uuid; BEGIN d:=governance.review_revision(rev,previous,'approved','Synthetic exact revision review'); RETURN governance.publish_revision(rev,d,previous); END $$;
